            { "WpfModelDetails.Runtime.53", new DefaultCatalogMigration("Ultralytics 패키지를 사용하는 YOLO11 실행 프로필입니다.", "A YOLO11 runtime profile using the Ultralytics package.") },
            { "WpfModelDetails.Runtime.50", new DefaultCatalogMigration("YOLOv8 local worker 폴더 연결", "Connect a YOLOv8 local worker folder") },
            { "WpfModelDetails.Runtime.49", new DefaultCatalogMigration("YOLOv5처럼 local YOLOv8 worker 폴더를 연결하는 실행 프로필입니다.", "A runtime profile that connects a local YOLOv8 worker folder, like YOLOv5.") },
            { "WpfModelDetails.Catalog.47", new DefaultCatalogMigration("Recipe 작업을 먼저 확인한 뒤 같은 Dataset Version에서 YOLOv8 대비 학습·평가를 시작하세요.", "Confirm the recipe task, then train and evaluate against YOLOv8 using the same Dataset Version.") },
            { "WpfModelDetails.Catalog.46", new DefaultCatalogMigration("같은 데이터 분할·가중치·실행 환경의 벤치마크만 비교합니다. 현재 이상분류 후보는 신뢰도 0.8에서 82/104로 hold이며 자동 채택하지 않습니다.", "Compare benchmarks only with the same split, weights, and runtime. The current anomaly-classification candidate is on hold at 82/104 with confidence 0.8; it is not adopted automatically.", ("같은 데이터 분할·모델 파일·실행 환경의 결과만 비교하세요. 현재 이상탐지 후보의 신뢰도 0.8 결과는 82/104로 보류 상태이며 검사 모델로 자동 지정하지 않습니다.", "Compare results only with the same dataset split, model files, and runtime. The current anomaly detection candidate is on hold at 82/104 with confidence 0.8. The inspection model is not set automatically."), ("같은 데이터 분할·모델 파일·실행 환경의 결과만 비교하세요.\r\n현재 이상탐지 후보의 신뢰도 0.8 결과는 82/104로 보류 상태이며 검사 모델로 자동 지정하지 않습니다.", "Compare results only with the same dataset split, model files, and runtime.\r\nThe current anomaly detection candidate is on hold at 82/104 with confidence 0.8. The inspection model is not set automatically.")) },
            { "WpfModelDetails.Catalog.45", new DefaultCatalogMigration("연결된 로컬 Ultralytics 실행기와 작업에 맞는 yolo11n.pt, yolo11n-seg.pt 또는 yolo11n-cls.pt를 사용합니다. 임의의 외부 YOLO11 포크는 검증 범위가 아닙니다.", "Uses a connected local Ultralytics runtime with task-matched yolo11n.pt, yolo11n-seg.pt, or yolo11n-cls.pt. Arbitrary external YOLO11 forks are outside the verified scope.", ("연결한 로컬 Ultralytics 환경과 작업에 맞는 yolo11n.pt, yolo11n-seg.pt 또는 yolo11n-cls.pt를 사용합니다. 외부 YOLO11 포크는 확인된 지원 범위에 포함되지 않습니다.", "Uses the connected local Ultralytics runtime with task-matched yolo11n.pt, yolo11n-seg.pt, or yolo11n-cls.pt. External YOLO11 forks are outside the verified scope."), ("연결한 로컬 Ultralytics 환경에서 작업에 맞춰 yolo11n.pt, yolo11n-seg.pt 또는 yolo11n-cls.pt를 사용합니다. 외부 YOLO11 포크는 지원 미확인입니다.", "Uses the connected local Ultralytics runtime with task-matched yolo11n.pt, yolo11n-seg.pt, or yolo11n-cls.pt. Support for external YOLO11 forks is unverified.")) },
            { "WpfModelDetails.Catalog.44", new DefaultCatalogMigration("객체탐지·세그멘테이션은 작업과 일치하는 native data.yaml과 YOLO 라벨을 사용합니다. 이상분류는 Recipe의 검토 완료 OK/NG 이미지를 고정 normal/abnormal 분할로 내보내며 원본을 덮어쓰지 않습니다.", "Detection and segmentation use task-matched native data.yaml and YOLO labels. Anomaly classification exports reviewed recipe OK/NG images into fixed normal/abnormal splits without overwriting sources.", ("객체 탐지·세그멘테이션은 작업에 맞는 native data.yaml과 YOLO 라벨을 사용합니다. 이상탐지는 검수 완료된 레시피 OK/NG 이미지를 normal/abnormal 분할로 내보냅니다. 원본은 덮어쓰지 않습니다.", "Object detection and segmentation use task-matched native data.yaml and YOLO labels. Anomaly detection exports reviewed recipe OK/NG images into normal/abnormal splits without overwriting the source."), ("객체 탐지·세그멘테이션은 작업에 맞는 native data.yaml과 YOLO 라벨을 사용합니다. 이상탐지는 OK/NG로 판정한 레시피 이미지를 normal/abnormal 분할로 내보냅니다. 원본은 덮어쓰지 않습니다.", "Object detection and segmentation use task-matched native data.yaml and YOLO labels. Anomaly detection exports recipe images judged OK or NG into normal/abnormal splits without overwriting the source."), ("객체 탐지·세그멘테이션은 작업에 맞는 native data.yaml과 YOLO 라벨을 씁니다. 이상탐지는 OK/NG로 판정한 레시피 이미지를 normal/abnormal 폴더로 내보냅니다. 원본은 덮어쓰지 않습니다.", "Object detection and segmentation use task-matched native data.yaml and YOLO labels. Anomaly detection exports recipe images judged OK or NG into normal/abnormal folders without overwriting the source.")) },
            { "WpfModelDetails.Catalog.43", new DefaultCatalogMigration("객체탐지, 세그멘테이션, 이상분류의 학습·검증·추론 및 YOLOv8 대비 실행을 지원합니다.", "Supports training, validation, inference, and comparison with YOLOv8 for detection, segmentation, and anomaly classification.") },
            { "WpfModelDetails.Catalog.42", new DefaultCatalogMigration("검증된 로컬 Ultralytics 객체탐지·세그멘테이션·이상분류 런타임", "Verified local Ultralytics detection, segmentation, and anomaly-classification runtime") },
            { "WpfModelDetails.Catalog.41", new DefaultCatalogMigration("변환된 데이터셋만으로 ONNX 모델의 학습·비교 가능성을 증명했다고 보지 마세요.", "A converted dataset alone does not prove that an ONNX model supports training or comparison.") },
            { "WpfModelDetails.Catalog.40", new DefaultCatalogMigration("비교 또는 채택을 결정하기 전에 추론 결과를 레시피 라벨과 검토해야 합니다.", "Review inference results against recipe labels before deciding on comparison or adoption.") },
            { "WpfModelDetails.Catalog.39", new DefaultCatalogMigration("검증된 ONNX 추론 프로필과 명시적 모델 아티팩트를 연결해야 합니다.", "Connect a verified ONNX inference profile and an explicit model artifact.") },
            { "WpfModelDetails.Catalog.38", new DefaultCatalogMigration("외부 모델은 호환되는 입력 크기·출력 구조·클래스 매핑·신뢰도 의미를 제공해야 합니다.", "External models must provide compatible input size, output structure, class mapping, and confidence semantics.") },
            { "WpfModelDetails.Catalog.37", new DefaultCatalogMigration("현재 이미지 또는 배치 추론만 지원하며, 앱 소유 ONNX 학습 경로는 없습니다.", "Supports current-image or batch inference only; the app has no ONNX training workflow.") },
            { "WpfModelDetails.Catalog.36", new DefaultCatalogMigration("추론 전용(Inference-only) 어댑터", "Inference-only adapter") },
            { "WpfModelDetails.Catalog.34", new DefaultCatalogMigration("정상 train 2장 이상과 가능하면 독립 normal val을 준비한 뒤 학습하고, 미확정 위치 후보와 heatmap을 검토하세요.", "Prepare at least 2 normal train images and preferably independent normal val data, then train and review unconfirmed location candidates and heatmaps.") },
            { "WpfModelDetails.Catalog.33", new DefaultCatalogMigration("히트맵과 위치 후보는 검토 보조이며 자동 라벨 저장이나 현장 결함 검출 성능을 보장하지 않습니다. 동일 held-out 데이터에서 YOLO 분류와 별도 비교해야 합니다.", "Heatmaps and location candidates support review; they do not save labels automatically or guarantee field defect-detection quality. Compare separately with YOLO classification on the same held-out data.") },
            { "WpfModelDetails.Catalog.32", new DefaultCatalogMigration("bundled openvisionlab_patchcore_worker.py와 torch·torchvision·numpy·Pillow를 사용합니다. 학습 결과 best.pt에는 특징 추출기와 메모리 뱅크를 포함합니다.", "Uses bundled openvisionlab_patchcore_worker.py with torch, torchvision, numpy, and Pillow. The resulting best.pt includes the feature extractor and memory bank.") },
            { "WpfModelDetails.Catalog.31", new DefaultCatalogMigration("검토 완료 normal train 이미지만 메모리 뱅크에 사용합니다. normal val은 임계값 보정에 사용하며, NG 이미지는 학습 특징에 포함하지 않습니다.", "Uses only reviewed normal train images for the memory bank. normal val calibrates the threshold; NG images never contribute training features.", ("검수 완료된 정상 학습 이미지만 메모리 뱅크에 사용합니다. 정상 검증 이미지는 판정 기준 보정에 쓰며, NG 이미지는 학습 특징에 포함하지 않습니다.", "Uses only reviewed normal training images for the memory bank. Normal validation images calibrate the judgement threshold; NG images do not contribute training features.")) },
            { "WpfModelDetails.Catalog.30", new DefaultCatalogMigration("이상탐지 Recipe에서 정상 이미지만 학습하고, 이미지 OK/NG 판정과 결함 위치 후보를 함께 반환합니다.", "Trains on normal images in an anomaly recipe and returns image OK/NG decisions with defect-location candidates.") },
            { "WpfModelDetails.Catalog.29", new DefaultCatalogMigration("로컬 PyTorch 정상-only 학습·추론 후보", "Local PyTorch normal-only training and inference candidate") },
            { "WpfModelDetails.Catalog.28", new DefaultCatalogMigration("PatchCore one-class 이상탐지", "PatchCore one-class anomaly detection") },
            { "WpfModelDetails.Catalog.27", new DefaultCatalogMigration("세그멘테이션 Recipe와 U-Net 실행기 상태를 확인한 뒤 학습 또는 U-Net/YOLO-seg 비교를 시작하세요.", "Check the segmentation recipe and U-Net runtime before training or U-Net/YOLO-seg comparison.") },
            { "WpfModelDetails.Catalog.26", new DefaultCatalogMigration("U-Net과 YOLO-seg는 같은 canonical test mask의 Dice/IoU로만 비교합니다. bbox mAP와 섞거나 결과로 자동 채택하지 않습니다.", "Compare U-Net and YOLO-seg only with Dice/IoU on the same canonical test masks. Do not combine bbox mAP or adopt results automatically.") },
            { "WpfModelDetails.Catalog.25", new DefaultCatalogMigration("격리된 U-Net PyTorch 환경과 번들 openvisionlab_unet_worker.py를 사용합니다. 시작 가중치 없이 학습한 호환 best.pt만 검사에 사용합니다.", "Uses an isolated U-Net PyTorch environment and bundled openvisionlab_unet_worker.py. Inspection accepts only compatible best.pt trained without seed weights.") },
            { "WpfModelDetails.Catalog.24", new DefaultCatalogMigration("Recipe 마스크/폴리곤 또는 명시적으로 활성화한 native YOLO segmentation data.yaml을 앱 소유 raster-mask export로 변환하며 원본은 변경하지 않습니다.", "Converts recipe masks/polygons or explicitly activated native YOLO segmentation data.yaml into app-owned raster-mask exports without changing the source.", ("레시피 마스크·폴리곤 또는 사용하도록 지정한 native YOLO segmentation data.yaml을 앱의 마스크 데이터로 변환합니다. 원본은 변경하지 않습니다.", "Converts recipe masks and polygons or an explicitly enabled native YOLO segmentation data.yaml into app-owned raster masks. The source remains unchanged.")) },
            { "WpfModelDetails.Catalog.23", new DefaultCatalogMigration("세그멘테이션만 지원합니다. 객체탐지 박스나 이상탐지 OK/NG 분류에는 사용하지 않습니다.", "Supports segmentation only. Do not use it for detection boxes or anomaly OK/NG classification.") },
            { "WpfModelDetails.Catalog.22", new DefaultCatalogMigration("검증된 로컬 PyTorch 학습·추론·비교 어댑터", "Verified local PyTorch training, inference, and comparison adapter") },
            { "WpfModelDetails.Catalog.20", new DefaultCatalogMigration("먼저 작업을 선택하고 학습 전에 데이터 준비 상태와 런타임을 확인하세요.", "Choose the task first, then check data and runtime readiness before training.") },
            { "WpfModelDetails.Catalog.19", new DefaultCatalogMigration("후보 런타임 성공, 홀드아웃 평가, 모델 채택은 서로 다른 결정입니다.", "Candidate runtime success, held-out evaluation, and model adoption are separate decisions.") },
            { "WpfModelDetails.Catalog.18", new DefaultCatalogMigration("로컬 Ultralytics 워커, 작업 인지 학습 요청, 정확한 가중치 식별자가 필요합니다.", "Requires a local Ultralytics worker, task-aware training requests, and exact weight identity.") },
            { "WpfModelDetails.Catalog.17", new DefaultCatalogMigration("레시피 소유 YOLO 내보내기 또는 원본 지문이 일치하는 명시적 활성화 native data.yaml을 사용합니다.", "Uses recipe-owned YOLO exports or explicitly activated native data.yaml with matching source fingerprints.", ("레시피에서 내보낸 YOLO 데이터나, 원본 확인 정보가 일치하고 사용하도록 지정한 native data.yaml을 사용합니다.", "Uses YOLO data exported from the recipe or an explicitly enabled native data.yaml with a matching source fingerprint.")) },
            { "WpfModelDetails.Catalog.16", new DefaultCatalogMigration("객체 탐지·세그멘테이션·이미지 단위 이상 분류는 각각 별도 작업 계약을 따릅니다.", "Detection, segmentation, and image-level anomaly classification follow separate task contracts.") },
