            { "WpfModelDetails.Catalog.12", new DefaultCatalogMigration("학습·예측 검토·비교에는 같은 분할/지문과 보존된 런타임·가중치 식별자가 필요합니다.", "Training, prediction review, and comparison require the same split/fingerprint and preserved runtime and weight identities.") },
            { "WpfModelDetails.Catalog.11", new DefaultCatalogMigration("실행 전 로컬 YOLOv5 프로필의 Python·저장소·클라이언트·가중치 경로가 모두 해석되어야 합니다.", "The local YOLOv5 profile must resolve Python, repository, client, and weight paths before execution.") },
            { "WpfModelDetails.Catalog.10", new DefaultCatalogMigration("클래스 순서, 정규화 xywh 박스, 선언된 분할을 갖는 레시피 소유 YOLO 탐지 디렉터리를 사용합니다.", "Uses recipe-owned YOLO detection directories with class order, normalized xywh boxes, and declared splits.") },
            { "WpfModelDetails.Catalog.8", new DefaultCatalogMigration("검증된 로컬 학습·추론 어댑터", "Verified local training and inference adapter") },
